# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MÜŞRİKLERİN TEPKİLERİ KARŞISINDA NEBEVÎ DAVET YÖNTEMİ (SYR.10.2.2-3)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">MÜŞRİKLERİN TEPKİ SEBEPLERİ VE ÇEŞİTLERİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#7f1d1d">• Dinî Sebep: Putperestlik ve «atalar dini» alışkanlığı</text>\n  <text x="35" y="112" font-size="11.2" fill="#7f1d1d">• Sosyal Sebep: Kabile üstünlüğü ve köle-efendi eşitliğine itiraz</text>\n  <text x="35" y="136" font-size="11.2" fill="#7f1d1d">• Ekonomik/Siyasi: Mekke liderliğini ve ticari çıkarı kaybetme</text>\n  <text x="35" y="160" font-size="11.2" fill="#7f1d1d">• Psikolojik Tepkiler: Alay, iftira (sihirbaz/şair), uzlaşma teklifi</text>\n  <text x="35" y="184" font-size="11.2" fill="#7f1d1d">• Fiziksel Tepkiler: İşkence, ambargo (boykot) ve suikast planı</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">HZ. PEYGAMBER\'İN İZLEDİĞİ DAVET İLKELERİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#1e3a8a">• Hikmet ve Güzel Öğüt (Nahl suresi 125. ayet ilkesi)</text>\n  <text x="370" y="112" font-size="11.2" fill="#1e3a8a">• Tevhid akidesinden asla taviz vermeme (ilkeli duruş)</text>\n  <text x="370" y="136" font-size="11.2" fill="#1e3a8a">• Dârü\'l-Erkam\'da sahâbîleri Kur\'an ve ahlakla eğitme</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• Şiddete şiddetle karşılık vermeyip sabır ve sükûneti koruma</text>\n  <text x="370" y="184" font-size="11.2" fill="#1e3a8a">• Mazlum Müslümanlar için güvenli hicret ve himaye arayışı</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hz. Peygamber (s.a.v.), müşriklerin baskılarını Kur\'an eğitimi, sabır ve stratejik adımlarla aşmıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HABEŞİSTAN HİCRETİ (615-616) VE BOYKOT YILLARI (616-619)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">HABEŞİSTAN HİCRETİ VE NECÂŞÎ</text>\n  <text x="35" y="88" font-size="11.2" fill="#14532d">• Amaç: İşkence gören Müslümanların can ve din güvenliği</text>\n  <text x="35" y="112" font-size="11.2" fill="#14532d">• «Orada yanında kimseye zulmedilmeyen adil bir hükümdar var»</text>\n  <text x="35" y="136" font-size="11.2" fill="#14532d">• I. Hicret (615): 11 erkek, 4 kadın (Hz. Osman ve Hz. Rukiyye)</text>\n  <text x="35" y="160" font-size="11.2" fill="#14532d">• II. Hicret (616): Cafer b. Ebî Tâlib başkanlığında ~100 sahâbî</text>\n  <text x="35" y="184" font-size="11.2" fill="#14532d">• Hz. Cafer\'in Necâşî huzurunda Meryem suresini okuması</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">HZ. HAMZA, HZ. ÖMER VE BOYKOT (616-619)</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">• Nübüvvetin 6. yılında Hz. Hamza ve Hz. Ömer Müslüman oldu</text>\n  <text x="370" y="112" font-size="11.2" fill="#7c2d12">• Müslümanlar Kâbe\'de ilk kez açıktan saf tutarak namaz kıldı</text>\n  <text x="370" y="136" font-size="11.2" fill="#7c2d12">• Müşrikler Haşimoğulları ve Muttaliboğullarına boykot ilan etti</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Şi\'b-i Ebî Tâlib mahallesinde 3 yıl süren ağır kuşatma</text>\n  <text x="370" y="184" font-size="11.2" fill="#7c2d12">• Sağduyulu 5 Kureyşlinin girişimiyle 619\'da boykot sona erdi</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Habeşistan Hicreti İslam\'ın Afrika\'ya ilk açılımı olmuş, boykot ise Müslümanların kenetlenmesini güçlendirmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HÜZÜN YILI, TÂİF YOLCULUĞU VE AKABE BİATLARI (619-622)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">HÜZÜN YILI (619) VE TÂİF YOLCULUĞU (620)</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">• Hüzün Yılı: Amcası Ebû Tâlib ve eşi Hz. Hatice\'nin vefatı</text>\n  <text x="35" y="112" font-size="11.2" fill="#581c87">• Mekke\'de himaye kalkınca Zeyd b. Hârise ile Tâif\'e gidiş</text>\n  <text x="35" y="136" font-size="11.2" fill="#581c87">• Sakîf kabilesinin taşlı saldırısına beddua değil dua ile yanıt</text>\n  <text x="35" y="160" font-size="11.2" fill="#581c87">• Ninovalı Hristiyan köle Addâs\'ın Müslüman olması</text>\n  <text x="35" y="184" font-size="11.2" fill="#581c87">• Mut\'im b. Adî\'nin himayesi (civâr) ile Mekke\'ye dönüş</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">PANAYIR TEBLİĞLERİ VE AKABE BİATLARI</text>\n  <text x="370" y="88" font-size="11.2" fill="#064e3b">• 620: Akabe\'de Medineli (Yesribli) 6 Hazrecli ile ilk görüşme</text>\n  <text x="370" y="112" font-size="11.2" fill="#064e3b">• I. Akabe Biatı (621): 12 Medineli; ahlaki ilkeler üzerine söz</text>\n  <text x="370" y="136" font-size="11.2" fill="#064e3b">• İlk Muallim: Mus\'ab b. Umeyr\'in Medine\'ye gönderilmesi</text>\n  <text x="370" y="160" font-size="11.2" fill="#064e3b">• II. Akabe Biatı (622): 73 erkek, 2 kadın (75 Medineli sahâbî)</text>\n  <text x="370" y="184" font-size="11.2" fill="#064e3b">• Hz. Peygamber\'i canları gibi koruma sözü ve Hicret\'e zemin</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Akabe Biatları ve Mus\'ab b. Umeyr\'in öğretmenliği, Yesrib\'i İslam\'ın yeni merkezi (Medine-i Münevvere) yapmıştır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
